import numpy as np


def residual_predict(noisy, predicted_residual):
    return np.asarray(noisy, dtype=np.float64) - np.asarray(predicted_residual, dtype=np.float64)


def total_variation(image):
    img = np.asarray(image, dtype=np.float64)
    dx = img[:, 1:] - img[:, :-1]
    dy = img[1:, :] - img[:-1, :]
    return float(np.abs(dx).sum() + np.abs(dy).sum())
